using System;
namespace LoopFive {
 public class Engine {
  public bool RequireRecordAcknowledgement;public Func<long> FreshInputBoundary;
  public void AcknowledgeRecordingVisible(int i){lock(Gate){Track t=Tracks[i];if((t.State!=PlayState.Recording&&t.State!=PlayState.Overdubbing)||!t.AwaitingRecordVisible)return;t.AwaitingRecordVisible=false;}}
  bool RequestCaptureEnd(Track t,bool stop){if(FreshInputBoundary==null)return false;long end=FreshInputBoundary();if(end==long.MinValue)return false;t.CaptureStopInputId=end;t.FinishToStopped=stop;return true;}
  void ArmCapture(Track t){t.CaptureLatencyFrames=System.LatencyCompMs*44.1+(System.AutoLatencyCompensation?AutomaticLatencyFrames:0);t.CaptureStopInputId=long.MaxValue;t.FinishToStopped=false;t.AwaitingRecordVisible=RequireRecordAcknowledgement;t.CaptureInputFloor=FreshInputBoundary==null?long.MinValue:FreshInputBoundary();t.FreshRecordedFrames=0;}
  bool CaptureAllowed(Track t,long[] ids,int i){return t.CaptureInputFloor==long.MinValue||ids!=null&&ids[i]>=t.CaptureInputFloor;}
  public readonly object Gate=new object();public SessionConfig Config=new SessionConfig();public SystemConfig System=new SystemConfig();public Track[] Tracks=new Track[5];
  public FxRack InputRack=new FxRack(),TrackRack=new FxRack();public RhythmEngine Drums=new RhythmEngine();public double Beat;public long Frames;public float InputPeak,OutputPeak;public int MidiNote=60,NoteCount;public string Status="Sin iniciar audio";public double AutomaticLatencyFrames;public int InputUnderruns;bool dirty;long revision;public bool Dirty{get{return dirty;}set{dirty=value;if(value)global::System.Threading.Interlocked.Increment(ref revision);}}public long Revision{get{return global::System.Threading.Interlocked.Read(ref revision);}}
  MicCleaner micCleaner=new MicCleaner();float[] carrierL=new float[7],carrierR=new float[7];bool individualInserts;float[] tl=new float[5],tr=new float[5];float inputEnvelope,masterEnvelope,eqLowL,eqLowR,eqTopL,eqTopR;long lastCountInBeat=-1;float gainLow=1,gainMid=1,gainHigh=1;FxProcessor masterReverb=new FxProcessor();FxConfig masterReverbConfig=new FxConfig{Type="REVERB",Amount=.6f};public const int MaxSamples=44100*60*10;
  public Engine(){for(int i=0;i<5;i++)Tracks[i]=new Track(Config.Tracks[i]);}
  public double BarBeats{get{return Config.Rhythm.BeatsPerBar*4.0/Config.Rhythm.Denominator;}}
  double SyncBoundary(){double cycle=BarBeats;if(Config.SyncMode==2){cycle=Config.LoopLengthBars*BarBeats;if(cycle<=0){foreach(Track t in Tracks)if(t.Clip!=null&&t.Config.LoopSync){cycle=Math.Max(BarBeats,t.Clip.Beats);break;}if(cycle<=0)cycle=BarBeats;}}return (Math.Floor(Beat/cycle+.000001)+1)*cycle;}
  double NextBar(){return (Math.Floor(Beat/BarBeats+.000001)+1)*BarBeats;}
  public void ResetDsp(){micCleaner=new MicCleaner();InputRack=new FxRack();TrackRack=new FxRack();Drums=new RhythmEngine();masterReverb=new FxProcessor();inputEnvelope=masterEnvelope=eqLowL=eqLowR=eqTopL=eqTopR=0;}
  public void SetCleanRecording(){lock(Gate){foreach(Track t in Tracks)if(t.State==PlayState.Recording||t.State==PlayState.Overdubbing)throw new InvalidOperationException("Termina la toma antes de aplicar la prueba limpia.");SetImmediateRecording();Config.MicCleanup=false;Config.Gate=0;Config.InputGain=1;Config.InputCompressor=false;Config.InputMute=false;Config.Monitor=false;Config.InputFx.Enabled=false;Config.TrackFx.Enabled=false;Config.MasterCompressor=false;Config.MasterReverb=0;Config.MasterLow=Config.MasterMid=Config.MasterHigh=0;Config.Master=.7f;Config.AutoTempo=false;foreach(Track t in Tracks){t.Config.Speed=1;t.Config.TempoSync=false;t.Config.Reverse=false;}ResetDsp();Dirty=true;}}
  public void SetImmediateRecording(){lock(Gate){Config.Quantize=false;Config.AutoRecord=false;Config.CountInBars=0;Config.SyncMode=0;foreach(Track t in Tracks)t.Config.StartMode=0;Dirty=true;}}
  public void SetTempo(float bpm){lock(Gate){Config.Bpm=MathX.Clamp(bpm,20,300);Dirty=true;}}
  public void Action(int index){lock(Gate){if(index<0||index>4)return;Config.SelectedTrack=index;Track t=Tracks[index];Dirty=true;
   if(t.State==PlayState.Armed||t.State==PlayState.WaitingRecord||t.State==PlayState.WaitingPlay){t.Stop();return;}
   if(t.State==PlayState.Recording){if(Config.Quantize&&t.Config.LoopSync){t.FinishBeat=Math.Max(t.RecordStartBeat+BarBeats,NextBar());}else if(!RequestCaptureEnd(t,false))FinishRecord(t);return;}
   if(t.Clip==null||t.Clip.Length==0){t.Snapshot();if(Config.AutoRecord){t.State=PlayState.Armed;return;}Queue(t,1);return;}
   if(!t.Playing){Queue(t,2);return;}
   if(t.Config.OneShot){StartPlay(t);return;}if(t.Config.Reverse)return;
   if(t.State==PlayState.Overdubbing){if(!RequestCaptureEnd(t,false))t.State=PlayState.Playing;}else{t.Snapshot();t.State=PlayState.Overdubbing;ArmCapture(t);}
  }}
  void Queue(Track t,int action){if(action==2&&Config.SinglePlay&&Config.SingleLoopEnd){foreach(Track other in Tracks)if(other!=t&&other.Playing){double speed=PlaybackRate(other);double remaining=(other.Clip.Length-other.Position)/speed; t.PendingBeat=Beat+remaining*Config.Bpm/(60*44100);t.PendingAction=action;t.State=PlayState.WaitingPlay;return;}}
   bool wait=t.Config.LoopSync&&(Config.Quantize||t.Config.StartMode==1||Config.SyncMode>0);if(wait||action==1&&Config.CountInBars>0){t.PendingBeat=wait?SyncBoundary():Beat;if(action==1)t.PendingBeat+=Config.CountInBars*BarBeats;t.PendingAction=action;t.State=action==1?PlayState.WaitingRecord:PlayState.WaitingPlay;}else if(action==1)BeginRecord(t);else StartPlay(t);
  }
  void BeginRecord(Track t){t.State=PlayState.Recording;ArmCapture(t);t.RecordL.Clear();t.RecordR.Clear();t.RecordStartBeat=Beat;t.FinishBeat=-1;t.PendingBeat=-1;t.Position=0;
   int measures=t.Config.Measures;if(measures==0&&Config.LoopLengthBars>0)measures=Config.LoopLengthBars;if(measures==0){foreach(Track other in Tracks)if(other!=t&&other.Clip!=null&&other.Config.LoopSync){measures=Math.Max(1,(int)Math.Round(other.Clip.Beats/BarBeats));break;}}
   if(measures>0)t.FinishBeat=Beat+measures*BarBeats;if(t.Config.MeasureBeats>0)t.FinishBeat=Beat+t.Config.MeasureBeats;int expected=(int)Math.Min(MaxSamples,44100*60/Config.Bpm*(measures>0?measures*BarBeats:BarBeats*4));if(t.RecordL.Capacity<expected){t.RecordL.Capacity=expected;t.RecordR.Capacity=expected;}
   if(Config.Rhythm.StartMode==1)Config.Rhythm.Enabled=true;
  }
  public void FinishRecord(Track t){bool stop=t.FinishToStopped;t.CaptureStopInputId=long.MaxValue;t.FinishToStopped=false;if(t.RecordL.Count<16){t.Stop();return;}double beats=Math.Max(.0001,Beat-t.RecordStartBeat);if(Config.AutoTempo&&!Config.Rhythm.Enabled){bool first=true;foreach(Track other in Tracks)if(other!=t&&(other.Clip!=null||other.State==PlayState.Recording))first=false;if(first){double bars=Math.Max(1,Math.Round(beats/BarBeats));float inferred=(float)(bars*BarBeats*60*44100/t.RecordL.Count);Config.Bpm=MathX.Clamp(inferred,20,300);beats=bars*BarBeats;Beat=beats;}}t.Clip=new AudioClip(t.RecordL.ToArray(),t.RecordR.ToArray(),Config.Bpm,beats);t.RecordL.Clear();t.RecordR.Clear();t.FinishBeat=-1;t.PendingBeat=-1;StartPlay(t);if(Config.RecToDub&&!t.Config.OneShot&&!t.Config.Reverse){t.Snapshot();t.State=PlayState.Overdubbing;}if(Config.Rhythm.StartMode==2)Config.Rhythm.Enabled=true;if(stop)t.Stop();Dirty=true;}
  void StartPlay(Track t){if(t.Clip==null||t.Clip.Length==0){t.Stop();return;}if(Config.SinglePlay)foreach(Track other in Tracks)if(other!=t&&other.Playing)other.Stop();t.State=PlayState.Playing;t.ActiveSpeed=t.Config.Speed;t.Position=0;t.GrainAge=0;t.GrainA=0;t.GrainB=-512;t.PendingBeat=-1;t.StopAtEnd=t.FadingOut=false;t.Fade=t.Config.FadeIn?0:1;if(Config.Rhythm.StartMode==1)Config.Rhythm.Enabled=true;}
  public void Play(int i){lock(Gate){Track t=Tracks[i];if(t.State==PlayState.Recording)FinishRecord(t);else if(t.Clip!=null&&!t.Playing)Queue(t,2);Config.SelectedTrack=i;}}
  public void Overdub(int i){lock(Gate){Track t=Tracks[i];if(t.Config.Reverse||t.Config.OneShot)return;if(t.State==PlayState.Recording){FinishRecord(t);if(t.State!=PlayState.Overdubbing){t.Snapshot();t.State=PlayState.Overdubbing;}}else if(t.Clip==null)Action(i);else if(t.State==PlayState.Overdubbing){if(!RequestCaptureEnd(t,false))t.State=PlayState.Playing;}else{if(!t.Playing)StartPlay(t);t.Snapshot();t.State=PlayState.Overdubbing;ArmCapture(t);}Dirty=true;}}
  public void Stop(int i,bool immediate){lock(Gate){Track t=Tracks[i];if(t.State==PlayState.Recording){if(!immediate&&RequestCaptureEnd(t,true))return;FinishRecord(t);t.Stop();return;}if(immediate||t.FadingOut||t.StopAtEnd||!t.Playing){t.Stop();return;}if(t.Config.StopMode==1){t.FadingOut=true;t.State=PlayState.Playing;}else if(t.Config.StopMode==2){t.StopAtEnd=true;t.State=PlayState.Playing;}else t.Stop();}}
  public void AllStart(){lock(Gate){foreach(Track t in Tracks)if(t.Config.AllStart&&t.Clip!=null)Queue(t,2);}}
  public void AllStop(bool immediate){lock(Gate){for(int i=0;i<5;i++)if(Tracks[i].Config.AllStop)Stop(i,immediate);if(Config.Rhythm.StopMode==1)Config.Rhythm.Enabled=false;else if(Config.Rhythm.StopMode==2)Config.Rhythm.Ending=true;}}
  public void ResetTransport(){lock(Gate){AllStop(true);Beat=0;Frames=0;Drums.Reset();}}
  public void Clear(int i){lock(Gate){Tracks[i].Clear();Dirty=true;}}
  public void Undo(int i,bool redo){lock(Gate){Tracks[i].Undo(redo);Dirty=true;}}
  public void Mark(int i,bool restore){lock(Gate){if(restore)Tracks[i].MarkBack();else Tracks[i].MarkSet();Dirty=true;}}
  public void Import(int i,AudioClip clip){lock(Gate){long total=clip.Length;for(int n=0;n<5;n++)if(n!=i){if(Tracks[n].Clip!=null)total+=Tracks[n].Clip.Length;total+=Tracks[n].RecordL.Count;}if(clip.Length>MaxSamples||total>MaxSamples*3L)throw new InvalidOperationException("Se superó el límite de 10 minutos por pista o 30 minutos por sesión.");Tracks[i].Snapshot();Tracks[i].Clip=clip;Tracks[i].Stop();Dirty=true;}}
  public void ToggleFx(bool input,int slot,bool down){lock(Gate){ChainConfig chain=input?Config.InputFx:Config.TrackFx;FxConfig f=chain.Slots[chain.Bank*4+slot];if(!down&&!f.Momentary)return;bool value=f.Momentary?down:!f.On;if(value&&chain.Single)for(int j=0;j<4;j++)chain.Slots[chain.Bank*4+j].On=false;f.On=value;Dirty=true;}}
  public double PlaybackRate(Track t){if(!Config.SpeedChangeLoopEnd)t.ActiveSpeed=t.Config.Speed;return Math.Max(.05,t.ActiveSpeed*(t.Config.TempoSync?Config.Bpm/Math.Max(20,t.Clip.Bpm):1));}
  float Read(Track t,float[] data,double p){return MathX.Sample(data,t.Config.Reverse?data.Length-1-p:p);}
  void TrackSample(Track t,out float l,out float r){l=r=0;if(!t.Playing||t.Clip==null||t.Clip.Length==0)return;double speed=PlaybackRate(t);if(t.Config.TempoSync&&t.Config.TempoMode==1&&Math.Abs(speed-t.ActiveSpeed)>.0001){int age=t.GrainAge%1024;if(age==0)t.GrainA=t.Position;if(age==512)t.GrainB=t.Position;int ageB=(age+512)%1024;double weight=.5-.5*Math.Cos(age*2*Math.PI/1024);double ap=t.GrainA+age*t.ActiveSpeed,bp=t.GrainB+ageB*t.ActiveSpeed;l=Read(t,t.Clip.L,ap)*(float)weight+Read(t,t.Clip.L,bp)*(float)(1-weight);r=Read(t,t.Clip.R,ap)*(float)weight+Read(t,t.Clip.R,bp)*(float)(1-weight);t.GrainAge++;}else{l=Read(t,t.Clip.L,t.Position);r=Read(t,t.Clip.R,t.Position);}
   if(t.Config.DubMode==2&&t.State==PlayState.Overdubbing)l=r=0;
   float fadeStep=Config.Bpm/(60*44100f);if(t.FadingOut){t.Fade-=fadeStep/Math.Max(.0625f,t.Config.FadeOutBeats);if(t.Fade<=0){t.Stop();l=r=0;return;}}else if(t.Fade<1)t.Fade=Math.Min(1,t.Fade+fadeStep/Math.Max(.0625f,t.Config.FadeInBeats));
   l*=t.Config.Level*t.Fade*(1-Math.Max(0,t.Config.Pan));r*=t.Config.Level*t.Fade*(1+Math.Min(0,t.Config.Pan));
  }
  long TotalSamples(){long n=0;foreach(Track t in Tracks){if(t.Clip!=null)n+=t.Clip.Length;n+=t.RecordL.Count;}return n;}
  public void Prepare(){InputRack.CarrierL=TrackRack.CarrierL=carrierL;InputRack.CarrierR=TrackRack.CarrierR=carrierR;individualInserts=TrackRack.HasTrackInserts(Config.TrackFx);InputRack.Prepare(Config.InputFx,Config.Bpm,MidiNote,NoteCount>0);TrackRack.Prepare(Config.TrackFx,Config.Bpm,MidiNote,NoteCount>0);Drums.Prepare(Config.Rhythm.Kit);masterReverbConfig.On=Config.MasterReverb>0;masterReverbConfig.Mix=Config.MasterReverb;masterReverb.Prepare(masterReverbConfig,Config.Bpm,MidiNote,false);gainLow=(float)Math.Pow(10,Config.MasterLow/20);gainMid=(float)Math.Pow(10,Config.MasterMid/20);gainHigh=(float)Math.Pow(10,Config.MasterHigh/20);}
  public void Process(float[] input,float[] output,int frames){Process(input,output,frames,null);}
  public void Process(float[] input,float[] output,int frames,long[] inputIds){lock(Gate){Prepare();micCleaner.Configure(Config);InputPeak*=.8f;OutputPeak*=.8f;bool solo=false;foreach(Track t in Tracks){t.Peak*=.8f;if(t.Config.Solo)solo=true;}
   for(int j=0;j<frames;j++){float il=input==null?0:MathX.Safe(input[j*2])*Config.InputGain,ir=input==null?0:MathX.Safe(input[j*2+1])*Config.InputGain;
    micCleaner.Tick(ref il,ref ir);if(Config.InputMute)il=ir=0;float pk=Math.Max(Math.Abs(il),Math.Abs(ir));InputPeak=Math.Max(InputPeak,pk);inputEnvelope+=(pk>inputEnvelope?.03f:.001f)*(pk-inputEnvelope);if(Config.Gate>0){float gateGain=MathX.Clamp(inputEnvelope/Math.Max(.000001f,Config.Gate),0,1);il*=gateGain;ir*=gateGain;}
    if(Config.InputCompressor&&inputEnvelope>.3f){float gain=(float)Math.Pow(.3/inputEnvelope,.7);il*=gain;ir*=gain;}

    bool counting=false;if(Config.CountInBars>0)foreach(Track waiting in Tracks)if(waiting.State==PlayState.WaitingRecord&&waiting.PendingBeat>=Beat&&Beat>=waiting.PendingBeat-Config.CountInBars*BarBeats)counting=true;if(counting){long pulse=(long)Math.Floor(Beat+1e-8);if(pulse!=lastCountInBeat){Drums.Hit(6,pulse%(long)Math.Max(1,BarBeats)==0?1:.65f);lastCountInBeat=pulse;}}else lastCountInBeat=-1;float rl,rr;Drums.Tick(Config.Rhythm,Beat,out rl,out rr);
    for(int i=0;i<5;i++){Track t=Tracks[i];if(t.CaptureStopInputId!=long.MaxValue&&inputIds!=null&&inputIds[j]>=t.CaptureStopInputId){if(t.State==PlayState.Recording)FinishRecord(t);else if(t.State==PlayState.Overdubbing){t.State=PlayState.Playing;t.CaptureStopInputId=long.MaxValue;}}if(t.State==PlayState.Overdubbing&&(t.Config.Reverse||t.Config.OneShot))t.State=PlayState.Playing;if(t.State==PlayState.Armed&&pk>=Config.AutoThreshold){Queue(t,1);}if(t.PendingBeat>=0&&Beat+1e-8>=t.PendingBeat){int action=t.PendingAction;t.PendingBeat=-1;if(action==1)BeginRecord(t);else StartPlay(t);}if(t.State==PlayState.Recording&&t.FinishBeat>=0&&Beat+1e-8>=t.FinishBeat)FinishRecord(t);TrackSample(t,out tl[i],out tr[i]);}
    for(int i=0;i<5;i++){Track source=Tracks[i];carrierL[i]=source.Playing&&source.Clip!=null?Read(source,source.Clip.L,source.Position):0;carrierR[i]=source.Playing&&source.Clip!=null?Read(source,source.Clip.R,source.Position):0;}carrierL[5]=carrierR[5]=il;carrierL[6]=carrierR[6]=ir;int im=Config.InputFx.Target;float fil=(im&1)!=0?il:0,fir=(im&2)!=0?ir:0;InputRack.Tick(Config.InputFx,ref fil,ref fir,Beat);if((im&1)==0)fil=il;if((im&2)==0)fir=ir;
    float effectedL=0,effectedR=0,bypassL=0,bypassR=0;
    for(int i=0;i<5;i++){Track t=Tracks[i];TrackConfig c=t.Config;float l=c.InputL?(c.Effects?fil:il):0,r=c.InputR?(c.Effects?fir:ir):0;if(c.RecordRhythm){l+=rl;r+=rr;}for(int b=0;b<5;b++)if(b!=i&&(c.BounceMask&(1<<b))!=0&&(!c.BounceAudibleOnly||(!Tracks[b].Config.Mute&&(!solo||Tracks[b].Config.Solo)))){l+=tl[b];r+=tr[b];}
     if(t.State==PlayState.Recording){if(t.RecordL.Count>=MaxSamples||TotalSamples()>=MaxSamples*3L){FinishRecord(t);Status="Se alcanzó el límite de audio por pista o sesión";}else{bool fresh=CaptureAllowed(t,inputIds,j);if(fresh){if(t.FreshRecordedFrames==0){double skipped=Beat-t.RecordStartBeat;t.RecordStartBeat=Beat;if(t.FinishBeat>=0)t.FinishBeat+=skipped;}t.FreshRecordedFrames++;t.RecordL.Add(MathX.Safe(l));t.RecordR.Add(MathX.Safe(r));}}}
     else if(t.State==PlayState.Overdubbing&&t.Clip!=null&&CaptureAllowed(t,inputIds,j)){t.FreshRecordedFrames++;int n=t.Clip.Length;double latency=t.CaptureLatencyFrames*PlaybackRate(t);int pos=(int)MathX.Wrap(t.Position-latency,n);float oldL=c.DubMode==0?t.Clip.L[pos]*c.Feedback:0,oldR=c.DubMode==0?t.Clip.R[pos]*c.Feedback:0;t.Clip.L[pos]=MathX.Safe(oldL+l);t.Clip.R[pos]=MathX.Safe(oldR+r);}
     if(t.Playing){t.Peak=Math.Max(t.Peak,Math.Max(Math.Abs(tl[i]),Math.Abs(tr[i])));if(!c.Mute&&(!solo||c.Solo)){if(c.Effects&&(Config.TrackFx.Target&(1<<i))!=0){float fxL=tl[i],fxR=tr[i];if(individualInserts)TrackRack.TickTrack(Config.TrackFx,i,ref fxL,ref fxR,Beat);effectedL+=fxL;effectedR+=fxR;}else{bypassL+=tl[i];bypassR+=tr[i];}}t.Position+=PlaybackRate(t);if(t.Position>=t.Clip.Length){if(c.OneShot||t.StopAtEnd)t.Stop();else{t.Position%=t.Clip.Length;if(Config.SpeedChangeLoopEnd)t.ActiveSpeed=t.Config.Speed;}}}
    }
    if(!individualInserts)TrackRack.Tick(Config.TrackFx,ref effectedL,ref effectedR,Beat);float ol=(effectedL+bypassL+rl+(Config.Monitor?fil:0))*Config.Master,orr=(effectedR+bypassR+rr+(Config.Monitor?fir:0))*Config.Master;
    eqLowL+=.028f*(ol-eqLowL);eqLowR+=.028f*(orr-eqLowR);eqTopL+=.43f*(ol-eqTopL);eqTopR+=.43f*(orr-eqTopR);ol=eqLowL*gainLow+(eqTopL-eqLowL)*gainMid+(ol-eqTopL)*gainHigh;orr=eqLowR*gainLow+(eqTopR-eqLowR)*gainMid+(orr-eqTopR)*gainHigh;masterReverb.Tick(ref ol,ref orr,Beat);float mp=Math.Max(Math.Abs(ol),Math.Abs(orr));masterEnvelope+=(mp>masterEnvelope?.01f:.0005f)*(mp-masterEnvelope);if(Config.MasterCompressor&&masterEnvelope>.35f){float mg=(float)Math.Pow(.35/masterEnvelope,.65);ol*=mg;orr*=mg;}ol=MathX.Safe(ol);orr=MathX.Safe(orr);if(Config.Limiter){float peak=Math.Max(Math.Abs(ol),Math.Abs(orr));if(peak>.98f){float gain=.98f/peak;ol*=gain;orr*=gain;}}
    output[j*2]=ol;output[j*2+1]=orr;OutputPeak=Math.Max(OutputPeak,Math.Max(Math.Abs(ol),Math.Abs(orr)));Beat+=Config.Bpm/(60.0*44100);Frames++;
   }
  }}
  public void Execute(string target,float value,bool trigger){lock(Gate){Dirty=true;if(target.StartsWith("Pista ")&&target.Length>7){int i=target[6]-'1';if(i<0||i>4)return;string action=target.Substring(8);Track t=Tracks[i];if(action=="REC"&&trigger)Action(i);if(action=="STOP"&&trigger)Stop(i,false);if(action=="UNDO"&&trigger)Undo(i,false);if(action=="REDO"&&trigger)Undo(i,true);if(action=="MARK"&&trigger)Mark(i,false);if(action=="MARK BACK"&&trigger)Mark(i,true);if(action=="CLEAR"&&trigger)Clear(i);if(action=="ONE SHOT"&&trigger)t.Config.OneShot=!t.Config.OneShot;if(action=="FX"&&trigger)t.Config.Effects=!t.Config.Effects;if(action=="SPEED")t.Config.Speed=value<.33f?.5f:value>.66f?2:1;if(action=="LEVEL")t.Config.Level=value*2;if(action=="PAN")t.Config.Pan=value*2-1;if(action=="MUTE"&&trigger)t.Config.Mute=!t.Config.Mute;if(action=="REVERSE"&&trigger)t.Config.Reverse=!t.Config.Reverse;return;}
   if(target=="Todos START"&&trigger)AllStart();if(target=="Todos STOP"&&trigger)AllStop(false);if(target=="Ritmo"&&trigger)Config.Rhythm.Enabled=!Config.Rhythm.Enabled;if(target=="Fill"&&trigger)Config.Rhythm.Fill=true;if(target=="AUTO REC"&&trigger)Config.AutoRecord=!Config.AutoRecord;if(target=="QUANTIZE"&&trigger)Config.Quantize=!Config.Quantize;if(target=="SINGLE"&&trigger)Config.SinglePlay=!Config.SinglePlay;if(target=="Ritmo LEVEL")Config.Rhythm.Level=value*2;if(target=="Input LEVEL")Config.InputGain=value*4;if(target=="Master")Config.Master=value;if(target=="Tempo")Config.Bpm=40+value*210;
   if(target.StartsWith("Input FX ")||target.StartsWith("Track FX ")){bool input=target.StartsWith("Input");int slot=target[target.Length-1]-'A';if(slot>=0&&slot<4&&trigger)ToggleFx(input,slot,true);}
  }}
 }
